-- ── story 1-6d: the licence enforcement switch ──────────────────────────────
-- Generated by drizzle-kit (the `licence_policies` table and its unique
-- index) and hand-amended: the fail-fast guard, RLS (the tenant arm — the
-- `expiry_alert_policies` 0049 shape; no portal arm, the switch is never a
-- portal read) and the post-migration probe (drizzle-kit is blind to all of
-- it; `bun run db:generate` afterwards reports "No schema changes").
--
-- Additive: one new tenant-scoped table, empty at deploy — a missing row
-- means enforcement is off, so every tenant keeps today's behaviour until an
-- owner turns it on. No data is rewritten. No foreign keys
-- (IMPLEMENTATION-GUIDE §3).

-- ── 0. fail-fast ─────────────────────────────────────────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'licence_policies'
	) THEN
		RAISE EXCEPTION 'migration 0085: the licence_policies table already exists — this migration has already been applied.';
	END IF;
END $$;
--> statement-breakpoint
CREATE TABLE "licence_policies" (
	"id" uuid PRIMARY KEY NOT NULL,
	"tenant_id" uuid NOT NULL,
	"enforce" boolean NOT NULL,
	"updated_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX "licence_policies_tenant_unique" ON "licence_policies" USING btree ("tenant_id");
--> statement-breakpoint
-- ── hand-amended: RLS — the tenant arm (migration SQL only) ───────────────
ALTER TABLE "licence_policies" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "licence_policies_tenant_isolation" ON "licence_policies"
	USING ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
	WITH CHECK ("tenant_id" = NULLIF(current_setting('app.tenant_id', true), '')::uuid);--> statement-breakpoint
-- ── the post-migration assertion (the 0084 model) ─────────────────────────
-- Made-up uuids. The accepted shape is inserted first and rolled back by a
-- sentinel exception, so a constraint that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused by the named constraint (the unique index, or NOT NULL on
-- `enforce`). The RLS arm is proved as `wms_rls_probe` in
-- test/licence-enforcement.spec.ts — the migrator is a superuser.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	probe text;
	expected text;
	refused_by text;
BEGIN
	BEGIN
		INSERT INTO "licence_policies" ("id","tenant_id","enforce","updated_by") VALUES (gen_random_uuid(), t, true, u);
		INSERT INTO "licence_policies" ("id","tenant_id","enforce","updated_by") VALUES (gen_random_uuid(), gen_random_uuid(), false, u);
		RAISE EXCEPTION 'probe-accepted-sentinel';
	EXCEPTION
		WHEN raise_exception THEN
			IF SQLERRM <> 'probe-accepted-sentinel' THEN
				RAISE;
			END IF;
	END;

	INSERT INTO "licence_policies" ("id","tenant_id","enforce","updated_by") VALUES (gen_random_uuid(), t, false, u);
	FOR probe, expected IN
		SELECT * FROM (VALUES
			('second row for a tenant', 'licence_policies_tenant_unique'),
			('enforce null', 'enforce')
		) AS p(probe, expected)
	LOOP
		refused_by := NULL;
		BEGIN
			CASE probe
				WHEN 'second row for a tenant' THEN
					INSERT INTO "licence_policies" ("id","tenant_id","enforce","updated_by") VALUES (gen_random_uuid(), t, true, u);
				WHEN 'enforce null' THEN
					INSERT INTO "licence_policies" ("id","tenant_id","enforce","updated_by") VALUES (gen_random_uuid(), gen_random_uuid(), NULL, u);
			END CASE;
		EXCEPTION
			WHEN unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
			WHEN not_null_violation THEN
				GET STACKED DIAGNOSTICS refused_by = COLUMN_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0085: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	DELETE FROM "licence_policies" WHERE "tenant_id" = t;
	IF EXISTS (SELECT 1 FROM "licence_policies") THEN
		RAISE EXCEPTION 'migration 0085: a probe row survived.';
	END IF;
END $$;
